<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;
use Civi\Lughauth\Shared\Value\Validation\Rule\Length;

class TemplateVariableValueVO
{
  public static function empty(): TemplateVariableValueVO
  {
      return new TemplateVariableValueVO(null);
  }
  public static function from(TemplateVariableValueVO|string|null $value): TemplateVariableValueVO
  {
    return self::fromUnsafe($value);
  }
  public static function tryFrom(mixed $value, ConstraintFailList $list): ?TemplateVariableValueVO
  {
    if ( $value instanceof TemplateVariableValueVO ) {
      // If is a ValueObject, its already validated... nothing to append
      return $value;
    } else if( !$value ) {
      return new TemplateVariableValueVO($value);
    } else if( is_string($value)) {
      // If is a ValueObject, we need to append all the errors for the context
      $valid = true;
      foreach (self::rules() as $rule) {
        if ($fail = $rule->check($value)) {
          $list->add(ConstraintFail::fromRuleFail('value', $fail));
          $valid = false;
        }
      }
      return $valid ? new TemplateVariableValueVO($value) : null;
    } else {
      $list->add(new ConstraintFail('wrong_type', ['value'], [$value], ['string']));
      return null;
    }
  }
  public static function rules(): array
  {
    return [
      new Length(min: null, max: 250),
    ];
  }
  private static function fromUnsafe(mixed $value): TemplateVariableValueVO
  {
    if ($value instanceof TemplateVariableValueVO) {
      // If is a ValueObject, its already validated
      return $value;
    } else {
      // If is not a ValueObject, validation is need and exception throw
      $errorsList = new ConstraintFailList();
      $candidate = self::tryFrom($value, $errorsList);
      if ($errorsList->hasErrors()) {
        throw $errorsList->asConstraintException();
      }
      \assert($candidate instanceof TemplateVariableValueVO);
      return $candidate;
    }
  }
  /**
   * private constructor to avoid build a value without all the rule validations.
   */
  private function __construct(
    private readonly ?string $value
  ) {
  }
  public function value(): ?string
  {
    return $this->value;
  }
  public function equals(?TemplateVariableValueVO $other): bool
  {
    return $this->value() == $other?->value();
  }
}
